logy\"}]','[]','[]','[]','[]',NULL,NULL,'[]','[{\"url\": \"/uploads/resumes/shobana-annadurai-1791464852-886.pdf\", \"title\": \"Shobana Annadurai\", \"isDefault\": false}]','[]'),('feae4e35-6c9e-4948-8aa0-9780c0382251','40701245-02b1-4b38-80d0-5902e3881011','Test Resume360','Test Resume360','Software Deve',2,NULL,NULL,NULL,'[\"Automation\"]','PUBLIC','2025-05-25 20:43:57.000000','2026-10-21 07:09:05.000000','[{\"title\": \"Software Deve\", \"company\": \"Sonata Software \", \"endDate\": \"\", \"isCurrent\": false, \"startDate\": \"\", \"description\": \"\"}]','[{\"year\": \"\", \"degree\": \"B.Tech\", \"result\": \"\", \"institution\": \"\"}]','[]','[]','[]','[]',NULL,NULL,'[]','[]','[]'),('feb219b1-a4dd-479d-ac41-0cfc1aac1373','b73878b4-6085-4c8b-9fd0-ea9d29a98483','Test Resume442','Test Resume442','Software Deve',2,NULL,NULL,NULL,'[\".NET\"]','PUBLIC','2025-05-24 21:28:48.000000','2026-10-21 07:09:04.000000','[{\"title\": \"Software Deve\", \"company\": \"TCS\", \"endDate\": \"\", \"isCurrent\": false, \"startDate\": \"\", \"description\": \"\"}]','[{\"year\": \"\", \"degree\": \"B.Tech\", \"result\": \"\", \"institution\": \"\"}]','[]','[]','[]','[]',NULL,NULL,'[]','[]','[]'),('feb5da13-61dc-408e-8a1a-5578a8d97fdb','c25ba07a-e143-4c22-82dd-762da9204cf0','Test Resume131','Test Resume131','Software Deve',2,NULL,NULL,NULL,'[\"Guidewire CC\"]','PUBLIC','2025-05-24 21:11:46.000000','2026-10-21 07:09:04.000000','[{\"title\": \"Software Deve\", \"company\": \"TCS\", \"endDate\": \"\", \"isCurrent\": false, \"startDate\": \"\", \"description\": \"\"}]','[{\"year\": \"\", \"degree\": \"B.Tech\", \"result\": \"\", \"institution\": \"\"}]','[]','[]','[]','[]',NULL,NULL,'[]','[]','[]'),('feb65c64-4336-4cdb-92c2-b0349fc0f88b','324f9aae-ca56-439f-8452-9a7f0c9a0a7a','Test Resume28','Test Resume28','Software Deve',2,NULL,NULL,NULL,'[\".NET\"]','PUBLIC','2025-05-26 07:33:26.000000','2026-10-21 07:09:05.000000','[{\"title\": \"Software Deve\", \"company\": \"ASPL\", \"endDate\": 