--
-- Table structure for table `job_postings`
--

DROP TABLE IF EXISTS `job_postings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_postings` (
  `id` varchar(36) NOT NULL,
  `tenant_id` varchar(255) NOT NULL,
  `posted_by_user_id` varchar(255) NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `category` varchar(100) NOT NULL,
  `employmentType` enum('Full-time','Part-time','Contract','Internship','Remote') NOT NULL DEFAULT 'Full-time',
  `experienceLevel` enum('Entry','Mid','Senior','Lead','Executive') NOT NULL DEFAULT 'Mid',
  `salaryMin` decimal(12,2) DEFAULT NULL,
  `salaryMax` decimal(12,2) DEFAULT NULL,
  `currency` varchar(10) NOT NULL DEFAULT 'USD',
  `isSalaryVisible` tinyint NOT NULL DEFAULT '1',
  `locationCountry` varchar(100) NOT NULL,
  `locationCity` varchar(100) NOT NULL,
  `isRemote` tinyint NOT NULL DEFAULT '0',
  `isFeatured` tinyint NOT NULL DEFAULT '0',
  `screeningQuestions` json DEFAULT NULL,
  `status` enum('DRAFT','PENDING_APPROVAL','PUBLISHED','EXPIRED','ARCHIVED') NOT NULL DEFAULT 'PUBLISHED',
  `expiresAt` timestamp NOT NULL,
  `viewsCount` int NOT NULL DEFAULT '0',
  `applicationsCount` int NOT NULL DEFAULT '0',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `applyType` varchar(20) NOT NULL DEFAULT 'INTERNAL',
  `applyUrl` varchar(500) DEFAULT NULL,
  `skills` json DEFAULT NULL,
  `benefits` json DEFAULT NULL,
  `genderPreference` varchar(20) NOT NULL DEFAULT 'ANY',
  `minExperience` int NOT NULL DEFAULT '0',
  `maxExperience` int NOT NULL DEFAULT '5',
  `locationState` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_71549ebdaf6647e51de711396c3` (`tenant_id`),
  KEY `FK_e24ab7cffe7b1ecfd256441581a` (`posted_by_user_id`),
  CONSTRAINT `FK_71549ebdaf6647e51de711396c3` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `FK_e24ab7cffe7b1ecfd256441581a` FOREIGN KEY (`posted_by_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `job_postings`
--

LOCK TABLES `job_postings` WRITE;
/*!40000 ALTER TABLE `job_postings` DISABLE KEYS */;
INSERT INTO `job_postings` VALUES ('002f9e3c-8ec6-4993-a6e0-cde1ca7cca5b','895c2926-0596-4115-a3e5-03a9d8fe042d','1ee4d080-3a60-4e83-ba83-d1de1e725d54','Techno Functional (Mainframe)','techno-functional-mainframe-263-263','&lt;p data-start=&quot;865&quot; data-end=&quot;1097&quot;&gt;&lt;strong data-start=&quot;868&quot; data-end=&quot;893&quot;&gt;Job Responsibilities:&lt;/strong&gt;&lt;br data-start=&quot;893&quot; data-end=&quot;896&quot; /&gt;&amp;nbsp;Solutioning for Manufacturing Domain&lt;br data-start=&quot;934&quot; data-end=&quot;937&quot; /&gt;&amp;nbsp;Design &amp;amp; Development of Manufacturing Functions and Interfaces&lt;br data-start=&quot;1001&quot; data-end=&quot;1004&quot; /&gt;&amp;nbsp;Working on Mainframe Technologies&lt;br data-start=&quot;1039&quot; data-end=&quot;1042&quot; /&gt;&amp;nbsp;Supporting Manufacturing / Metals Industry Projects&lt;/p&gt;\r\n&lt;p data-start=&quot;1099&quot; data-end=&quot;1266&quot;&gt;&amp;nbsp;Candidates with experience in MES, Manufacturing, Steel, Metals, Mainframe Solutioning, COBOL Development, DB2, IMS, and Functional Consulting are highly preferred.&lt;/p&gt;','Information Technology','Contract','Mid',NULL,NULL,'₹',0,'India','Kolkata',0,0,NULL,'PUBLISHED','2026-07-10 06:00:00',0,0,'2026-05-11 15:24:37.000000','2026-05-11 15:24:37.000000','INTERNAL',NULL,'[\"COBOL\", \"IMS (IP Multimedia Subsystem)\", \"Manufacturing\", \"DB2\", \"Mainframe\", \"Solution Design\"]','[\"Work with Top MNC\"]','No Preference',1,5,'West Bengal'),('004447d8-c7e2-4a8c-bf94-6142b772c4ca','895c2926-0596-4115-a3e5-03a9d8fe042d','1ee4d080-3a60-4e83-ba83-d1de1e725d54','Veeva QMS Support Analyst','veeva-qms-support-analyst-383-383','&lt;p class=&quot;PDq2pG_selectionAnchorContainer&quot; data-start=&quot;93&quot; data-end=&quot;305&quot;&gt;We are hiring experienced &lt;strong data-start=&quot;119&quot; data-end=&quot;179&quot;&gt;Veeva QMS Support Analysts / Veeva Vault QMS Consultants&lt;/strong&gt; for a leading Top MNC to work on critical &lt;strong data-start=&quot;222&quot; data-end=&quot;292&quot;&gt;Life Sciences, Pharmaceutical, Biotechnology, and Manufacturing IT&lt;/strong&gt; initiatives.&lt;/p&gt;\r\n&lt;p data-start=&quot;307&quot; data-end=&quot;604&quot;&gt;The ideal candidate should have strong hands-on experience with &lt;strong data-start=&quot;371&quot; data-end=&quot;398&quot;&gt;Veeva QMS / Veeva Vault&lt;/strong&gt;, including configuration, implementation, consulting, production support, and live project delivery. Strong knowledge of regulated pharmaceutical environments and quality management processes is essential.&lt;/p&gt;\r\n&lt;p data-start=&quot;606&quot; data-end=&quot;845&quot;&gt;The role involves supporting and improving key QMS processes such as &lt;strong data-start=&quot;675&quot; data-end=&quot;760&quot;&gt;CAPA, Change Control, Quality Risk Assessments (QARs), Investigations, and Events&lt;/strong&gt;, while ensuring compliance with &lt;strong data-start=&quot;793&quot; data-end=&quot;844&quot;&gt;GxP, FDA, ISO, CSV, and IT quality requirements&lt;/strong&gt;.&lt;/p&gt;\r\n&lt;p data-start=&quot;847&quot; data-end=&quot;1113&quot;&gt;The candidate will collaborate with business users, Quality teams, IT stakeholders, validation teams, and global project teams to deliver reliable Veeva QMS solutions, support qualification activities, manage migrations, and drive continuous improvement initiatives.&lt;/p&gt;','Information Technology','Contract','Mid',NULL,NULL,'₹',0,'India','PAN India',0,0,NULL,'PUBLISHED','2026-11-02 07:00:00',0,0,'2026-09-04 02:14:20.000000','2026-09-04 02:14:20.000000','INTERNAL',NULL,'[\".NET\", \"API\", \"CSV\", \"Gxp Compliance\", \"HTML\", \"Java\", \"PL/SQL\", \"Troubleshooting\", \"XML\", \"Change Control Management\", \"Veeva Vault\", \"Veeva QMS\", \"Veeva QMS Configuration\", \"Veeva Vault Configuration\", \"CAPA\", \"Quality Management Systems\", \"QARs\"]','[\"&lt;ul&gt;\\r\\n&lt;li data-section-id=&quot;rdheb3&quot; data-start=&quot;1128&quot; data-end=&quot;1175&quot;&gt;Opportunity to work with a leading global MNC&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;4b3swh&quot; data-start=&quot;1176&quot; data-end=&quot;1254&quot;&gt;Exposure to enterprise-scale &lt;strong data-start=&quot;1207&quot; data-end=&quot;1226&quot;&gt;Veeva Vault QMS&lt;/strong&gt; implementations and support&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;6olqve&quot; data-start=&quot;1255&quot; data-end=&quot;1327&quot;&gt;Work on critical &lt;strong data-start=&quot;1274&quot; data-end=&quot;1318&quot;&gt;Pharma, Biotechnology, and Life Sciences&lt;/strong&gt; projects&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1xurxsx&quot; data-start=&quot;1328&quot; data-end=&quot;1395&quot;&gt;Exposure to regulated &lt;strong data-start=&quot;1352&quot; data-end=&quot;1382&quot;&gt;GxP and Quality Management&lt;/strong&gt; environments&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1axqg8d&quot; data-start=&quot;1396&quot; data-end=&quot;1484&quot;&gt;Opportunity to work on CAPA, Change Control, Investigations, Events, and QMS processes&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;79u91z&quot; data-start=&quot;1485&quot; data-end=&quot;1556&quot;&gt;Experience with validation, qualification, and compliance initiatives&lt;/li&gt;\\r\\n&lt;/ul&gt;\"]','No Preference',1,5,'PAN India'),('0059dc7a-255b-4feb-9e20-992894e624c4','3ec4391c-d7e6-4810-9ac1-64f6e207fd8d','537b19b2-0785-46b6-9899-ed1f166a0469','SDE 3 Wipro','sde-3-wipro','gr','Engineering','Full-time','Senior',120000.00,160000.00,'USD',1,'United States','Pune',1,0,'[]','PUBLISHED','2026-12-08 03:40:15',0,0,'2026-10-09 03:40:15.308615','2026-10-16 05:31:40.000000','INTERNAL',NULL,'[\"Java\", \"Spring Boot\", \"SQL\", \"Microservices\"]',NULL,'ANY',0,5,NULL),('0094ba3b-cab7-44c0-bfd1-8194828b9e0c','17bcd594-d749-4baa-8493-ad59b499fe1f','1ee4d080-3a60-4e83-ba83-d1de1e725d54','DevOps Engineer','devops-engineer-251-251','&lt;p data-start=&quot;2330&quot; data-end=&quot;2353&quot;&gt;&lt;strong data-start=&quot;2330&quot; data-end=&quot;2351&quot;&gt;Responsibilities:&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul data-start=&quot;2354&quot; data-end=&quot;2494&quot;&gt;\r\n&lt;li data-section-id=&quot;8gdi2v&quot; data-start=&quot;2354&quot; data-end=&quot;2390&quot;&gt;Build and manage CI/CD pipelines&lt;/li&gt;\r\n&lt;li data-section-id=&quot;1tnu4ko&quot; data-start=&quot;2391&quot; data-end=&quot;2435&quot;&gt;Deploy applications on cloud (AWS/Azure)&lt;/li&gt;\r\n&lt;li data-section-id=&quot;1gg8ugp&quot; data-start=&quot;2436&quot; data-end=&quot;2466&quot;&gt;Monitor system performance&lt;/li&gt;\r\n&lt;li data-section-id=&quot;1mmy55p&quot; data-start=&quot;2467&quot; data-end=&quot;2494&quot;&gt;Automate infrastructure&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p data-start=&quot;2496&quot; data-end=&quot;2560&quot;&gt;&lt;strong data-start=&quot;2496&quot; data-end=&quot;2516&quot;&gt;Required Skills:&lt;/strong&gt;&lt;br data-start=&quot;2516&quot; data-end=&quot;2519&quot; /&gt;AWS, Docker, Kubernetes, Jenkins, Linux&lt;/p&gt;','Information Technology','Contract','Entry',NULL,NULL,'INR',1,'India','PAN India',0,0,NULL,'PUBLISHED','2026-06-16 06:00:00',0,0,'2026-04-17 23:35:42.000000','2026-04-17 23:35:42.000000','INTERNAL',NULL,'[\"AWS\", \"Docker\", \"Jenkins\", \"Kubernetes\", \"Linux\"]','[\"&lt;ul&gt;\\r\\n&lt;li data-section-id=&quot;1b8ludi&quot; data-start=&quot;57&quot; data-end=&quot;112&quot;&gt;Competitive salary and performance-based incentives&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;wa1cqy&quot; data-start=&quot;113&quot; data-end=&quot;152&quot;&gt;Health insurance (medical coverage)&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1elu4nz&quot; data-start=&quot;153&quot; data-end=&quot;191&quot;&gt;Paid leaves (casual, sick, earned)&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1sa4caw&quot; data-start=&quot;192&quot; data-end=&quot;243&quot;&gt;Flexible working hours / Work-from-home options&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;17iplkr&quot; data-start=&quot;244&quot; data-end=&quot;288&quot;&gt;Career growth and learning opportunities&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1uu5yk4&quot; data-start=&quot;289&quot; data-end=&quot;327&quot;&gt;Training and certification support&lt;/li&gt;\\r\\n&lt;/ul&gt;\"]','No Preference',1,5,'PAN India'),('0186a4f2-e9ac-44fe-a6d8-d8c244acdd22','17bcd594-d749-4baa-8493-ad59b499fe1f','1ee4d080-3a60-4e83-ba83-d1de1e725d54','DCS Engineer','dcs-engineer-168-168','&lt;p data-start=&quot;147&quot; data-end=&quot;650&quot;&gt;The DCS Engineer will be responsible for designing, configuring, testing, and troubleshooting Distributed Control Systems (DCS) within industrial automation environments. The role includes working with SCADA, PLC systems, HMI configurations, and industrial communication protocols such as Modbus and OPC UA.&lt;br data-start=&quot;454&quot; data-end=&quot;457&quot; /&gt;The ideal candidate will have strong hands-on experience in process automation and digital solutions, along with proficiency in Functional Block and Structured Text programming for DCS control.&lt;/p&gt;\r\n&lt;p data-start=&quot;652&quot; data-end=&quot;810&quot;&gt;You will be involved in system configuration, runtime diagnostics, integration testing, security testing, and resolving issues using advanced debugging tools.&lt;/p&gt;','Information Technology','Full-time','Mid',NULL,NULL,'₹',0,'India','Hyderabad',0,0,NULL,'PUBLISHED','2026-04-10 06:00:00',0,0,'2025-12-11 15:31:38.000000','2026-02-09 17:46:57.000000','INTERNAL',NULL,'[\"Automation\", \"PLC\", \"SCADA\", \"DCS\", \"HMI\", \"Modbus\", \"OPC UA\", \"Functional Block\"]','[\"&lt;ul data-start=&quot;1808&quot; data-end=&quot;2221&quot;&gt;\\r\\n&lt;li data-start=&quot;1808&quot; data-end=&quot;1850&quot;&gt;\\r\\n&lt;p data-start=&quot;1810&quot; data-end=&quot;1850&quot;&gt;Competitive salary based on experience&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;1851&quot; data-end=&quot;1916&quot;&gt;\\r\\n&lt;p data-start=&quot;1853&quot; data-end=&quot;1916&quot;&gt;Opportunity to work on advanced industrial automation systems&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;1917&quot; data-end=&quot;1978&quot;&gt;\\r\\n&lt;p data-start=&quot;1919&quot; data-end=&quot;1978&quot;&gt;Exposure to EcoStruxure Foxboro &amp;amp; modern DCS technologies&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;1979&quot; data-end=&quot;2044&quot;&gt;\\r\\n&lt;p data-start=&quot;1981&quot; data-end=&quot;2044&quot;&gt;Professional growth in process automation &amp;amp; digital solutions&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;2045&quot; data-end=&quot;2107&quot;&gt;\\r\\n&lt;p data-start=&quot;2047&quot; data-end=&quot;2107&quot;&gt;Collaborative and high-performance engineering environment&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;2108&quot; data-end=&quot;2165&quot;&gt;\\r\\n&lt;p data-start=&quot;2110&quot; data-end=&quot;2165&quot;&gt;Training opportunities for advanced DCS / SCADA tools&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;2166&quot; data-end=&quot;2221&quot;&gt;\\r\\n&lt;p data-start=&quot;2168&quot; data-end=&quot;2221&quot;&gt;Health insurance and company-wide employee benefits&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;/ul&gt;\"]','No Preference',1,5,'Telangana'),('0229275c-ecaf-41ba-bb83-c8545a9470df','17bcd594-d749-4baa-8493-ad59b499fe1f','1ee4d080-3a60-4e83-ba83-d1de1e725d54','MES Scrum Master','mes-scrum-master-308-308','&lt;p class=&quot;PDq2pG_selectionAnchorContainer&quot; data-start=&quot;58&quot; data-end=&quot;396&quot;&gt;We are hiring experienced MES Scrum Masters for a leading Top MNC to drive Agile delivery and digital manufacturing transformation programs. The ideal candidate should have strong expertise in Scrum methodologies, Manufacturing Execution Systems (MES), stakeholder management, and Agile project delivery within manufacturing environments.&lt;/p&gt;\r\n&lt;p data-start=&quot;398&quot; data-end=&quot;770&quot;&gt;The candidate will be responsible for leading Agile teams, facilitating Scrum ceremonies, and ensuring successful delivery of MES implementation and enhancement projects. The role includes coaching teams on Agile best practices, removing delivery impediments, managing stakeholder expectations, and driving continuous improvement initiatives across manufacturing programs.&lt;/p&gt;\r\n&lt;p data-start=&quot;772&quot; data-end=&quot;1116&quot;&gt;Professionals should have hands-on experience in Manufacturing Execution Systems, Agile/Scrum frameworks, sprint planning, backlog management, governance processes, and service delivery management. Experience with Siemens Opcenter Core (Camstar), end-to-end MES implementations, and manufacturing transformation initiatives is highly preferred.&lt;/p&gt;\r\n&lt;p data-start=&quot;1118&quot; data-end=&quot;1473&quot;&gt;The role also involves monitoring Agile metrics, managing customer relationships, ensuring SLA compliance, facilitating governance reviews, coordinating cross-functional teams, and supporting Product Owners in backlog prioritization. Candidates should possess strong leadership, communication, conflict resolution, negotiation, and problem-solving skills.&lt;/p&gt;','Information Technology','Contract','Mid',NULL,NULL,'₹',0,'India','PAN India',0,0,NULL,'PUBLISHED','2026-08-23 06:00:00',0,0,'2026-06-25 02:54:10.000000','2026-06-25 02:54:10.000000','INTERNAL',NULL,'[\"Agile Methodology\", \"KPI MONITORING\", \"Mes\", \"Siemens Opcenter\", \"SLA Management\", \"Stakeholder Management\", \"Scrum Master\", \"Change Control Management\", \"Scrum Framework\"]','[\"&lt;ul&gt;\\r\\n&lt;li data-section-id=&quot;j985z7&quot; data-start=&quot;1489&quot; data-end=&quot;1527&quot;&gt;Opportunity to work with a Top MNC&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;rhfow6&quot; data-start=&quot;1528&quot; data-end=&quot;1606&quot;&gt;Exposure to enterprise-scale MES and Manufacturing Transformation programs&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;x4z2au&quot; data-start=&quot;1607&quot; data-end=&quot;1682&quot;&gt;Leadership role in Agile delivery and digital manufacturing initiatives&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;13qji02&quot; data-start=&quot;1683&quot; data-end=&quot;1760&quot;&gt;Opportunity to collaborate with global manufacturing and technology teams&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1lbrefl&quot; data-start=&quot;1761&quot; data-end=&quot;1835&quot;&gt;Career growth in Agile Delivery, MES &amp;amp; Manufacturing Technology domain&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;65o1vi&quot; data-start=&quot;1836&quot; data-end=&quot;1891&quot;&gt;Professional and innovation-driven work environment&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1i65dym&quot; data-start=&quot;1892&quot; data-end=&quot;1935&quot;&gt;Competitive salary and benefits package&lt;/li&gt;\\r\\n&lt;/ul&gt;\"]','No Preference',1,5,'PAN India'),('024dc757-1813-4383-9541-2653e2522a00','895c2926-0596-4115-a3e5-03a9d8fe042d','1ee4d080-3a60-4e83-ba83-d1de1e725d54','Senior IoT / ThingWorx Developer','senior-iot-thingworx-developer-295-295','&lt;p data-start=&quot;74&quot; data-end=&quot;430&quot;&gt;We are hiring experienced Senior IoT / ThingWorx Developers for a leading Top MNC to work on Smart Manufacturing, Industry 4.0, Industrial IoT (IIoT), and Manufacturing Digital Transformation projects. The ideal candidate should have strong expertise in PTC ThingWorx, manufacturing IT systems, IoT architectures, and enterprise-scale industrial solutions.&lt;/p&gt;\r\n&lt;p data-start=&quot;432&quot; data-end=&quot;808&quot;&gt;The candidate will be responsible for designing, developing, and implementing scalable IoT applications and connected manufacturing solutions using the ThingWorx platform. The role includes developing high-performance applications, conducting proof of concepts (POCs), supporting smart factory initiatives, and delivering innovative solutions for global manufacturing clients.&lt;/p&gt;\r\n&lt;p data-start=&quot;810&quot; data-end=&quot;1151&quot;&gt;Professionals should have hands-on experience with Industrial IoT solutions, MES, SCADA/HMI, LIMS, EAM systems, manufacturing IT architecture, and shop-floor digitalization initiatives. Strong understanding of manufacturing processes, value stream mapping, application portfolio assessment, and ROI framework development is highly preferred.&lt;/p&gt;\r\n&lt;p data-start=&quot;1153&quot; data-end=&quot;1511&quot;&gt;The role also involves leading technical teams, mentoring developers, participating in architectural reviews, supporting Industry 4.0 implementations, and driving continuous improvement initiatives. Candidates should possess strong analytical, problem-solving, communication, and leadership skills with the ability to work in complex enterprise environments.&lt;/p&gt;','Information Technology','Contract','Mid',NULL,NULL,'₹',0,'India','PAN India',0,0,NULL,'PUBLISHED','2026-08-22 06:00:00',0,0,'2026-06-24 02:32:20.000000','2026-06-24 02:32:20.000000','INTERNAL',NULL,'[\"Lims\", \"Mes\", \"SCADA\", \"SDLC\", \"HMI\", \"PTC ThingWorx Platform\", \"Smart Factory\", \"Industrial IoT (IIoT)\"]','[\"&lt;ul&gt;\\r\\n&lt;li data-section-id=&quot;j985z7&quot; data-start=&quot;1527&quot; data-end=&quot;1565&quot;&gt;Opportunity to work with a Top MNC&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;18yzlgk&quot; data-start=&quot;1566&quot; data-end=&quot;1627&quot;&gt;Exposure to Smart Manufacturing and Industry 4.0 projects&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1obh9ja&quot; data-start=&quot;1628&quot; data-end=&quot;1690&quot;&gt;Work on advanced Industrial IoT and ThingWorx technologies&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;n64kxj&quot; data-start=&quot;1691&quot; data-end=&quot;1755&quot;&gt;Career growth in Manufacturing Digital Transformation domain&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;8vszhn&quot; data-start=&quot;1756&quot; data-end=&quot;1820&quot;&gt;Opportunity to collaborate with global manufacturing clients&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;o2ta5m&quot; data-start=&quot;1821&quot; data-end=&quot;1863&quot;&gt;Leadership and mentoring opportunities&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;65o1vi&quot; data-start=&quot;1864&quot; data-end=&quot;1919&quot;&gt;Professional and innovation-driven work environment&lt;/li&gt;\\r\\n&lt;li data-section-id=&quot;1i65dym&quot; data-start=&quot;1920&quot; data-end=&quot;1963&quot;&gt;Competitive salary and benefits package&lt;/li&gt;\\r\\n&lt;/ul&gt;\"]','No Preference',1,5,'PAN India'),('030a1810-a905-45ea-9eec-70f76e61d6fa','17bcd594-d749-4baa-8493-ad59b499fe1f','1ee4d080-3a60-4e83-ba83-d1de1e725d54','HxGN EAM / Cognos BI Developer','hxgn-eam-cognos-bi-developer-148-148','&lt;p data-start=&quot;206&quot; data-end=&quot;665&quot;&gt;We are looking for an experienced and detail-oriented &lt;strong data-start=&quot;260&quot; data-end=&quot;301&quot;&gt;HxGN EAM BI Report (Cognos) Developer&lt;/strong&gt; to design, build, and maintain advanced Business Intelligence solutions for enterprise asset management operations.&lt;br data-start=&quot;417&quot; data-end=&quot;420&quot; /&gt;The ideal candidate will have strong expertise in &lt;strong data-start=&quot;470&quot; data-end=&quot;564&quot;&gt;Cognos reporting, SQL (Oracle &amp;amp; SQL Server), APIs, integrations, and Hexagon EAM ecosystem&lt;/strong&gt;, along with the ability to translate business requirements into highly effective analytical outputs.&lt;/p&gt;\r\n&lt;p data-start=&quot;667&quot; data-end=&quot;887&quot;&gt;This role requires hands-on experience with &lt;strong data-start=&quot;711&quot; data-end=&quot;791&quot;&gt;EAM workflows, reporting structures, data lakes/UDH, and system integrations&lt;/strong&gt;, ensuring delivery of high-quality, accurate, and impactful analytics to business stakeholders.&lt;/p&gt;\r\n&lt;h3 data-start=&quot;889&quot; data-end=&quot;917&quot;&gt;&lt;strong data-start=&quot;893&quot; data-end=&quot;917&quot;&gt;Key Responsibilities&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul data-start=&quot;918&quot; data-end=&quot;2079&quot;&gt;\r\n&lt;li data-start=&quot;918&quot; data-end=&quot;1001&quot;&gt;\r\n&lt;p data-start=&quot;920&quot; data-end=&quot;1001&quot;&gt;Develop Cognos reports, dashboards, inboxes, KPIs, and charts for EAM operations.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1002&quot; data-end=&quot;1097&quot;&gt;\r\n&lt;p data-start=&quot;1004&quot; data-end=&quot;1097&quot;&gt;Create user-defined screens, grids, and Flex Business Rules for customized EAM functionality.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1098&quot; data-end=&quot;1154&quot;&gt;\r\n&lt;p data-start=&quot;1100&quot; data-end=&quot;1154&quot;&gt;Implement and manage alert systems within Hexagon EAM.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1155&quot; data-end=&quot;1275&quot;&gt;\r\n&lt;p data-start=&quot;1157&quot; data-end=&quot;1275&quot;&gt;Work with &lt;strong data-start=&quot;1167&quot; data-end=&quot;1184&quot;&gt;Oracle PL/SQL&lt;/strong&gt; and &lt;strong data-start=&quot;1189&quot; data-end=&quot;1209&quot;&gt;SQL Server T-SQL&lt;/strong&gt; for data extraction, transformation, optimization, and reporting.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1276&quot; data-end=&quot;1345&quot;&gt;\r\n&lt;p data-start=&quot;1278&quot; data-end=&quot;1345&quot;&gt;Manage Hexagon EAM utilities, including Import &amp;amp; Upload operations.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1346&quot; data-end=&quot;1450&quot;&gt;\r\n&lt;p data-start=&quot;1348&quot; data-end=&quot;1450&quot;&gt;Work on integrations using &lt;strong data-start=&quot;1375&quot; data-end=&quot;1415&quot;&gt;Infor ION, ION API, REST, SOAP, XSLT&lt;/strong&gt;, and other web service frameworks.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1451&quot; data-end=&quot;1566&quot;&gt;\r\n&lt;p data-start=&quot;1453&quot; data-end=&quot;1566&quot;&gt;Collaborate with cross-functional teams to gather reporting requirements and convert them into technical designs.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1567&quot; data-end=&quot;1666&quot;&gt;\r\n&lt;p data-start=&quot;1569&quot; data-end=&quot;1666&quot;&gt;Ensure high-quality data accuracy, performance optimization, and consistency across BI solutions.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1667&quot; data-end=&quot;1740&quot;&gt;\r\n&lt;p data-start=&quot;1669&quot; data-end=&quot;1740&quot;&gt;Understand EAM system workflows, data models, and reporting structures.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1741&quot; data-end=&quot;1819&quot;&gt;\r\n&lt;p data-start=&quot;1743&quot; data-end=&quot;1819&quot;&gt;Perform data validation, cleansing, and transformation to support analytics.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1820&quot; data-end=&quot;1919&quot;&gt;\r\n&lt;p data-start=&quot;1822&quot; data-end=&quot;1919&quot;&gt;Provide support, troubleshooting, and enhancements for existing Cognos BI reports and dashboards.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;1920&quot; data-end=&quot;2008&quot;&gt;\r\n&lt;p data-start=&quot;1922&quot; data-end=&quot;2008&quot;&gt;Document technical specifications, integration workflows, and data modeling standards.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;2009&quot; data-end=&quot;2079&quot;&gt;\r\n&lt;p data-start=&quot;2011&quot; data-end=&quot;2079&quot;&gt;Participate in Agile-based development and implementation processes.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3 data-start=&quot;2081&quot; data-end=&quot;2101&quot;&gt;&lt;strong data-start=&quot;2085&quot; data-end=&quot;2101&quot;&gt;Good to Have&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul data-start=&quot;2102&quot; data-end=&quot;2292&quot;&gt;\r\n&lt;li data-start=&quot;2102&quot; data-end=&quot;2173&quot;&gt;\r\n&lt;p data-start=&quot;2104&quot; data-end=&quot;2173&quot;&gt;Experience in designing &lt;strong data-start=&quot;2128&quot; data-end=&quot;2151&quot;&gt;Power BI dashboards&lt;/strong&gt; for EAM data sources.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;2174&quot; data-end=&quot;2244&quot;&gt;\r\n&lt;p data-start=&quot;2176&quot; data-end=&quot;2244&quot;&gt;Knowledge of &lt;strong data-start=&quot;2189&quot; data-end=&quot;2209&quot;&gt;Python scripting&lt;/strong&gt; for automation or data processing.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;li data-start=&quot;2245&quot; data-end=&quot;2292&quot;&gt;\r\n&lt;p data-start=&quot;2247&quot; data-end=&quot;2292&quot;&gt;Familiarity with the Extensibility Framework.&lt;/p&gt;\r\n&lt;/li&gt;\r\n&lt;/ul&gt;','Information Technology','Full-time','Mid',NULL,NULL,'₹',0,'India','Pune',0,0,NULL,'PUBLISHED','2026-01-24 07:00:00',0,0,'2025-11-26 02:06:11.000000','2025-11-26 02:06:11.000000','INTERNAL',NULL,'[\"Agile Methodology\", \"Configurations\", \"Data Lake\", \"Data Validation\", \"Oracle\", \"PL/SQL\", \"Reporting\", \"REST API\", \"SOAP\", \"SQL Performance Tuning\", \"SQL Server\", \"Troubleshooting\", \"Transact-SQL(T-SQL)\", \"XSLT\", \"UDH\", \"Cognos BI\", \"HxGN EAM\", \"Infor ION\"]','[\"&lt;ul data-start=&quot;166&quot; data-end=&quot;810&quot;&gt;\\r\\n&lt;li data-start=&quot;166&quot; data-end=&quot;223&quot;&gt;\\r\\n&lt;p data-start=&quot;168&quot; data-end=&quot;223&quot;&gt;&lt;strong data-start=&quot;168&quot; data-end=&quot;221&quot;&gt;Competitive Salary &amp;amp; Performance-Based Incentives&lt;/strong&gt;&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;224&quot; data-end=&quot;277&quot;&gt;\\r\\n&lt;p data-start=&quot;226&quot; data-end=&quot;277&quot;&gt;&lt;strong data-start=&quot;226&quot; data-end=&quot;275&quot;&gt;Opportunity to work with a leading Global MNC&lt;/strong&gt;&lt;/p&gt;\\r\\n&lt;/li&gt;\\r\\n&lt;li data-start=&quot;278&quot; data-end=&quot;356&quot;&gt;\\r\\n&lt;p data-start=&quot;280&quot; data-end=&quot;356&quot;&gt;&lt;strong