DROP TABLE IF EXISTS `login_activities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `login_activities` (
  `id` varchar(36) NOT NULL,
  `userId` varchar(36) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `userName` varchar(255) DEFAULT NULL,
  `role` varchar(50) DEFAULT NULL,
  `ipAddress` varchar(64) NOT NULL DEFAULT '127.0.0.1',
  `userAgent` text,
  `deviceType` varchar(50) NOT NULL DEFAULT 'Desktop',
  `browser` varchar(100) DEFAULT NULL,
  `os` varchar(100) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'SUCCESS',
  `failureReason` varchar(255) DEFAULT NULL,
  `loginMethod` varchar(50) NOT NULL DEFAULT 'PASSWORD',
  `location` varchar(150) DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `IDX_c377206365d1e5b49abc060a68` (`userId`),
  KEY `IDX_d1aa8fc57ad9533fc7e99ca3f7` (`email`),
  KEY `IDX_61df2a66bd2b90f29461a7e7ed` (`ipAddress`),
  KEY `IDX_96ddca3af7b9a2945bb5b95af2` (`status`,`createdAt`),
  KEY `IDX_3929e1dda25350d9c531566a56` (`email`,`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
