INSERT INTO `tenants` VALUES ('2e150e1a-ce0f-490f-b609-ee1f5954ef02','Toshi Automation Solutions Limited','COMPANY','toshi-automation-solutions-limited-18',NULL,'https://toshiautomation.com/',NULL,'Manufacturing','\"Toshi Automation Solutions Ltd. is the top Industrial Automation Company among warehouse automation companies in India. We\'re best automatic gates manufacturer &amp; automatic doors supplier of high speed doors &amp; rolling shutters in Ghaziabad. Entrance: automatic gates, sliding gate, swing gate, retractable gate, cleanroom doors in Ghaziabad, industrial gates, gate operators, gate motors, clean room doors, fire rated doors, goods lift in Ghaziabad. remote control gates, garage doors, industrial doors, sensor doors in Ghaziabad, bollards, turnstiles, flap barriers, boom barriers, Hydraulic &amp; Goods Lift Manufacturer in Ghaziabad Hygiene: hand dryers in Ghaziabad, sensor taps in Ghaziabad, urinal sensors in Ghaziabad, automatic taps in Ghaziabad\"','ACTIVE','2025-06-16 08:54:24.000000','2026-10-21 07:09:04.000000',1),('2eee15ab-8c6e-4f17-934a-c884e0d3bd62','Three Gee Solutions Pvt Ltd','COMPANY','three-gee-solutions-pvt-ltd-9',NULL,'https://3gsolutions.co.in/','9818333994','IT Services & Consulting','IT Services','ACTIVE','2025-05-29 04:51:09.000000','2026-10-21 07:09:04.000000',1),('3ba8503c-a327-4ddb-9b93-1f10e6095bcd','Approved Acme Corp','COMPANY','approved-acme-corp-7772','https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&q=80&w=120','https://example.com','TAX-VERIFIED','Software & SaaS','Registered hiring company.','ACTIVE','2026-10-22 05:16:30.518762','2026-10-22 05:16:30.518762',1),('3bbe27d0-2dda-4da5-b7b3-e1029bcfa39d','Innomax IT Solutions','COMPANY','innomax-it-solutions-47',NULL,NULL,NULL,'Technology',NULL,'ACTIVE','2025-12-04 16:52:14.000000','2026-10-21 07:09:04.000000',1),('3ec4391c-d7e6-4810-9ac1-64f6e207fd8d','FinTech Dynamics Corp','COMPANY','fintech-dynamics','https://images.unsplash.com/photo-155